        } else {
            brief.push_str(" When the caller asks for the operator, end with ");
            brief.push_str(RETURN_SENTINEL);
            brief.push_str(". Do not claim that a switchboard tool is available.");
        }
        brief.push_str(" Keep spoken updates brief and plain; leave code, paths, and detail in written output.");
        brief
    }

    async fn run_prepare(&self, project: &Project) -> String {
        if project.prepare.is_empty() {
            return String::new();
        }
        let mut command = if project.is_remote() {
            let remote = format!(
                "cd {} && {}",
                crate::pi_client::shell_quote(&project.cwd),
                project.prepare
            );
            let mut command = Command::new("ssh");
            command.args([
                "-T",
                "-o",
                "BatchMode=yes",
                "-o",
                "ConnectTimeout=10",
                project.host.as_deref().unwrap_or_default(),
                &remote,
            ]);
            command
        } else {
            let mut command = Command::new("sh");
            command.args(["-c", project.prepare.as_str()]);
            if !project.cwd.is_empty() {
                command.current_dir(&project.cwd);
            }
            command
        };
        command
            .envs(&self.env)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        crate::pi_client::isolate_process(&mut command);
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(error) => {
                tracing::warn!(project = %project.id, %error, "prepare could not start");
                return String::new();
            }
        };
        let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
        let stdout_task = child.stdout.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, PREPARE_OUTPUT_LIMIT).await
            })
        });
        let stderr_task = child.stderr.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, CHILD_ERROR_LIMIT).await
            })
        });
        let status = match timeout(Duration::from_secs(120), child.wait()).await {
            Ok(Ok(status)) => {
                process_guard.disarm();
                status
            }
            Ok(Err(error)) => {
                tracing::warn!(project = %project.id, %error, "prepare failed");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return String::new();
            }
            Err(_) => {
                tracing::warn!(project = %project.id, "prepare timed out");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return String::new();
            }
        };
        let stdout = join_output(stdout_task).await;
        let stderr = join_output(stderr_task).await;
        if stdout.truncated {
            tracing::warn!(project = %project.id, "prepare output exceeded the size limit");
            return "workspace refresh output was too large".into();
        }
        let report = String::from_utf8_lossy(&stdout.bytes).trim().to_owned();
        if !status.success() {
            let detail = String::from_utf8_lossy(&stderr.bytes)
                .trim()
                .chars()
                .take(300)
                .collect::<String>();
            tracing::warn!(project = %project.id, code = ?status.code(), %detail, "prepare exited unsuccessfully");
            return if report.is_empty() {
                format!(
                    "could not be refreshed ({})",
                    if detail.is_empty() {
                        "unknown error"
                    } else {
                        &detail
                    }
                )
            } else {
                report
            };
        }
        if !report.is_empty() {
            tracing::info!(project = %project.id, %report, "prepare reported the state of the working copy");
        }
        report
    }

    async fn stage_extension(&self, host: &str) -> Option<String> {
        if let Some(staged) = self.staged_extensions.lock().await.get(host).cloned() {
            return staged;
        }
        let staged = self.upload_extension(host).await;
        self.staged_extensions
            .lock()
            .await
            .insert(host.to_owned(), staged.clone());
        staged
    }

    async fn upload_extension(&self, host: &str) -> Option<String> {
        self.upload_extension_with("ssh", host).await
    }

    async fn upload_extension_with(&self, ssh_program: &str, host: &str) -> Option<String> {
        // Silently returning None here costs the agent its `speak` and
        // `diagram` tools and quietly rewrites its system prompt to use the
        // sentinel instead — a large behavior change from one unset path.
        let Some(source) = self.agent_extension_file.as_deref() else {
            tracing::warn!(
                host,
                "no agent extension file to stage; using sentinel fallback"
            );
            return None;
        };
        let contents = match tokio::fs::read(source).await {
            Ok(contents) => contents,
            Err(error) => {
                tracing::warn!(%error, source, "could not read project extension; using sentinel fallback");
                return None;
            }
        };
        let name = Path::new(source).file_name()?.to_string_lossy();
        let cache = self.remote_cache_dir.trim_end_matches('/');
        let target = format!("{cache}/{name}");
        let cache_path = if cache.starts_with('/') {
            crate::pi_client::shell_quote(cache)
        } else {
            format!("\"$HOME\"/{}", crate::pi_client::shell_quote(cache))
        };
        let target_path = if target.starts_with('/') {
            crate::pi_client::shell_quote(&target)
        } else {
            format!("\"$HOME\"/{}", crate::pi_client::shell_quote(&target))
        };
        let command = format!(
            "set -e; mkdir -p {cache_path}; cat > {target_path}; printf '%s' {target_path}"
        );
        let mut stage_command = Command::new(ssh_program);
        stage_command
            .args([
                "-T",
                "-o",
                "BatchMode=yes",
                "-o",
                "ConnectTimeout=10",
                host,
                &command,
            ])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        crate::pi_client::isolate_process(&mut stage_command);
        let mut child = match stage_command.spawn() {
            Ok(child) => child,
            Err(error) => {
                tracing::warn!(%error, host, "could not stage project extension; using sentinel fallback");
                return None;
            }
        };
        let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
        let mut stdin = child.stdin.take();
        let stdout_task = child.stdout.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, STAGE_OUTPUT_LIMIT).await
            })
        });
        let stderr_task = child.stderr.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, CHILD_ERROR_LIMIT).await
            })
        });
        let interaction = async {
            if let Some(mut input) = stdin.take() {
                match input.write_all(&contents).await {
                    Ok(()) => {}
                    // The remote stopped reading, which normally means the
                    // staging command already failed. Its exit status and
                    // stderr name the real cause -- a missing directory, a
                    // permission denial -- and that is what the warning below
                    // should carry, not the broken pipe it caused.
                    Err(error) if error.kind() == std::io::ErrorKind::BrokenPipe => {}
                    Err(error) => return Err(error),
                }
                drop(input);
            }
            child.wait().await
        };
        let status = match timeout(Duration::from_secs(30), interaction).await {
            Ok(Ok(status)) => {
                process_guard.disarm();
                status
            }
            Ok(Err(error)) => {
                tracing::warn!(%error, host, "remote extension staging failed; using sentinel fallback");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return None;
            }
            Err(_) => {
                tracing::warn!(
                    host,
                    "remote extension staging timed out; using sentinel fallback"
                );
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return None;
            }
        };
        let stdout = join_output(stdout_task).await;
        let stderr = join_output(stderr_task).await;
        if !status.success() || stdout.truncated {
            let detail = String::from_utf8_lossy(&stderr.bytes)
                .trim()
                .chars()
                .take(300)
                .collect::<String>();
            tracing::warn!(
                ?detail,
                host,
                code = ?status.code(),
                truncated = stdout.truncated,
                "remote extension staging failed; using sentinel fallback"
            );
            return None;
        }
        let staged = String::from_utf8_lossy(&stdout.bytes).trim().to_owned();
        if staged.is_empty() {
            tracing::warn!(
                host,
                "remote extension staging reported no path; using sentinel fallback"
            );
            return None;
        }
        tracing::info!(host, path = %staged, "staged the switchboard tool");
        Some(staged)
    }

    fn agent_env(&self, session_token: &str) -> HashMap<String, String> {
        let mut e = HashMap::from([
            (String::from("SWITCHBOARD_SESSION"), String::from("1")),
            (
                String::from("SWITCHBOARD_SESSION_TOKEN"),
                session_token.to_owned(),
            ),
        ]);
        for (key, value) in [
            ("SWITCHBOARD_SPEAK_URL", &self.speak_url),
            ("SWITCHBOARD_STATE_URL", &self.state_url),
            ("SWITCHBOARD_DIAGRAM_URL", &self.diagram_url),
            ("SWITCHBOARD_PERSONA", &self.persona),
        ] {
            if !value.is_empty() {
                e.insert(key.into(), value.clone());
            }
        }
        e
    }
    async fn load_catalog(&mut self, project: &Project) {
        let key = format!(
            "{}\0{}",
            project.host.as_deref().unwrap_or(""),
            project.runtime
        );
        if let std::collections::hash_map::Entry::Vacant(e) = self.catalogs.entry(key) {
            let catalog = fetch_catalog(&crate::pi_client::list_models_argv(
                &project.runtime,
                project.host.as_deref().unwrap_or(""),
            ))
            .await;
            e.insert(catalog);
        }
    }

    async fn resolve_model(
        &mut self,
        project: &Project,
        model: &str,
        thinking: &str,
    ) -> Result<ModelChoice, ModelError> {
        let requested = if model.is_empty() {
            project
                .model
                .as_deref()
                .or(self.agent_model.as_deref())
                .unwrap_or("")
                .to_owned()
        } else {
            model.to_owned()
        };
        self.load_catalog(project).await;
        let key = format!(
            "{}\0{}",
            project.host.as_deref().unwrap_or(""),
            project.runtime
        );
        self.catalogs
            .get(&key)
            .ok_or_else(|| ModelError("the model catalog was unavailable".into()))?
            .resolve(&requested, thinking)
    }

    async fn select_transfer_model(
        &mut self,
        project: &Project,
        requested_model: &str,
        requested_thinking: &str,
    ) -> (String, String) {
        let fallback = pin_thinking(
            project
                .model
                .as_deref()
                .or(self.agent_model.as_deref())
                .unwrap_or(""),
            &self.agent_thinking,
        );
        if !self.model_swaps {
            return (fallback, String::new());
        }
        if requested_model.trim().is_empty() {
            self.load_catalog(project).await;
            return (fallback, String::new());
        }

        match self
            .resolve_model(project, requested_model, requested_thinking)
            .await
        {
            Ok(choice) => (
                pin_thinking(&choice.spec(), &self.agent_thinking),
                String::new(),
            ),
            Err(error) => (fallback, format!("About the model: {error}")),
        }
    }

    async fn redial(
        &mut self,
        model: &str,
        thinking: &str,
        intent: &str,
        keep_context: bool,
    ) -> Reply {
        let Some(project) = self.project.clone() else {
            return self.reply(["There is no project on the line."], None);
        };
        if !self.model_swaps {
            return self.reply(["Model swapping is turned off on this switchboard."], None);
        }
        let requested_model = if model.is_empty() && !self.model_spec.is_empty() {
            self.model_spec.clone()
        } else {
            model.to_owned()
        };
        let (_, _, current_thinking) = crate::models::parse_spec(&self.model_spec);
        let level = if thinking.is_empty() {
            if !current_thinking.is_empty() {
                current_thinking
            } else {
                self.agent_thinking.clone()
            }
        } else {
            match normalize_thinking(thinking) {
                Ok(v) => v,
                Err(e) => return self.reply([e.to_string()], Some(e.to_string())),
            }
        };
        let choice = match self.resolve_model(&project, &requested_model, &level).await {
            Ok(choice) => choice,
            Err(error) => {
                // Refusing is the safe outcome — the live leg keeps running —
                // but it looks identical to a swap that never happened.
                tracing::info!(project = %project.id, requested = %requested_model, %error, "refusing a model swap");
                return self.reply(
                    [format!("I didn't switch: {error}")],
                    Some(error.to_string()),
                );
            }
        };
        let spec = choice.spec();
        if keep_context && spec == self.model_spec {
            return self.reply([format!("Already on {}.", choice.spoken())], None);
        }
        let session_id = if keep_context {
            self.session_id.clone()
        } else {
            uuid_like()
        };
        tracing::info!(
            project = %project.id,
            from = %self.model_spec,
            to = %spec,
            context = if keep_context { "kept" } else { "cleared" },
            "swapping the model on the live leg"
        );
        self.drop_agent().await;
        self.project = Some(project.clone());
        self.route = project.id.clone();
        self.live_leg.set_session(&self.route, &session_id);
        self.session_id = session_id.clone();
        self.model_spec = spec.clone();
        match self.start_agent(&project, &spec, &session_id).await {
            Ok(session) => {
                let project_name = project.id.clone();
                self.agent = Some(session);
                self.route = project.id.clone();
                self.live_leg.set_session(&self.route, &session_id);
                self.project = Some(project);
                self.session_id = session_id;
                self.model_spec = spec.clone();
                // Keep route ownership coherent if a forced page action aborts
                // the redial while its session handle is being published.
                self.set_active_session(self.agent.clone()).await;
                self.announce_route().await;
                let prompt = if keep_context {
                    format!(
                        "You are now running on {spec}. Continue the conversation.{}",
                        if intent.trim().is_empty() {
                            String::new()
                        } else {
                            format!(" The caller also asked: {}.", intent.trim())
                        }
                    )
                } else {
                    format!(
                        "You are now running on {spec}. The earlier conversation was deliberately cleared; start fresh.{}",
                        if intent.trim().is_empty() {
                            String::new()
                        } else {
                            format!(" The caller asked: {}.", intent.trim())
                        }
                    )
                };
                let Some(session) = self.agent.clone() else {
                    return self
                        .return_operator("project session disappeared during redial")
                        .await;
                };
                let turn = match session.prompt(&prompt).await {
                    Ok(turn) => turn,
                    Err(error) => Turn {
                        text: String::new(),
                        signals: vec![],
                        failed: true,
                        error: error.to_string(),
                    },
                };
                if turn.failed && turn.text.is_empty() {
                    let detail = if turn.error.is_empty() {
                        session.stderr_tail(5)
                    } else {
                        turn.error.clone()
                    };
                    let detail = if detail.is_empty() {
                        "the agent never answered".to_owned()
                    } else {
                        detail
                    };
                    tracing::error!(project = %project_name, %spec, %detail, "the swapped leg never answered");
                    self.drop_agent().await;
                    self.operator_note = Some(format!(
                        "{project_name} could not be restarted on {spec}: {detail}"
                    ));
                    return self.reply(
                        [format!(
                            "{project_name} didn't come back on {spec}: {detail}"
                        )],
                        Some(detail),
                    );
                }
                self.reply_with_turn(turn)
            }
            Err(error) => {
                tracing::error!(project = %project.id, %spec, %error, "could not restart the leg on the new model");
                self.drop_agent().await;
                let note = format!("{} could not be restarted on {}: {error}", project.id, spec);
                self.operator_note = Some(note);
                self.reply(
                    [format!(
                        "I couldn't bring {} back on {}: {error}",
                        project.id, spec
                    )],
                    Some(error.to_string()),
                )
            }
        }
    }
    async fn return_operator(&mut self, note: &str) -> Reply {
        self.drop_agent().await;
        // Prompt the operator immediately so an onward destination in the note
        // is acted on now, not stapled onto the caller's next utterance.
        let note = note.to_owned();
        let reply = self.handle_operator(&format!("[switchboard] {note}")).await;
        if reply.error.is_some() {
            self.operator_note = Some(note);
        }
        if reply.text.is_empty() {
            self.reply(["You're back with the operator."], reply.error)
        } else {
            reply
        }
    }
    async fn recover_operator(&mut self, error: String) -> Reply {
        tracing::warn!(%error, "dropping and rebuilding the operator leg");
        if let Some(s) = self.operator.take() {
            s.close().await;
        }
        self.set_active_session(None).await;
        self.reply(
            ["The operator dropped the line. Say that again and I'll pick it back up."],
            Some(error),
        )
    }
    async fn drop_agent(&mut self) {
        let was = self.route.clone();
        if let Some(s) = self.agent.take() {
            s.close().await;
        }
        self.set_active_session(self.operator.clone()).await;
        self.project = None;
        self.route = OPERATOR.into();
        self.live_leg.set_route(OPERATOR);
        self.model_spec.clear();
        self.session_id.clear();
        if was != OPERATOR {
            self.announce_route().await;
        }
    }
    fn reply<I, S>(&self, texts: I, error: Option<String>) -> Reply
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        Reply::new(
            &self.route,
            &self.route_label(),
            texts
                .into_iter()
                .map(|text| Utterance {
                    text: text.into(),
                    synthesize: true,
                })
                .collect(),
            error,
        )
    }
    fn reply_with_turn(&self, turn: Turn) -> Reply {
        let spoke = turn.agent_spoke();
        let failed = turn.failed;
        let error = turn.error;
        Reply::new(
            &self.route,
            &self.route_label(),
            vec![Utterance {
                text: turn.text,
                synthesize: !spoke,
            }],
            failed.then_some(error),
        )
    }
    fn reply_transfer_error(
        &self,
        handoff: String,
        message: String,
        error: Option<String>,
    ) -> Reply {
        Reply::new(
            &self.route,
            &self.route_label(),
            vec![
                Utterance {
                    text: handoff,


… payload truncated

content.text:
                .return_operator(&format!(
                    "The caller was handed back from {}.{summary}",
                    self.route_label()
                ))
                .await;
            self.prepend_utterance(&text, synthesize && reply.route == OPERATOR, &mut reply);
            return reply;
        }
        self.reply_with_turn(turn)
    }
    async fn transfer(
        &mut self,
        spoken: &str,
        intent: &str,
        handoff: String,
        requested_model: &str,
        requested_thinking: &str,
    ) -> Reply {
        let Some(project) = self.registry.resolve(spoken).cloned() else {
            tracing::warn!(from = %self.route, requested = spoken, "transfer to an unknown project");
            let known = self.registry.ids();
            let known_text = if known.is_empty() {
                "nothing yet".to_owned()
            } else {
                known.join(", ")
            };
            let from = (self.route != OPERATOR).then(|| self.route_label());
            if from.is_some() {
                self.drop_agent().await;
            }
            self.operator_note = Some(format!(
                "Transfer to {spoken:?} failed. Known projects: {known_text}.{}",
                from.map(|name| format!(" The caller was on {name}."))
                    .unwrap_or_default()
            ));
            return self.reply_transfer_error(
                handoff,
                format!("I don't have a project called {spoken}. I know: {known_text}."),
                Some(format!("unknown project {spoken:?}")),
            );
        };
        tracing::info!(
            from = %self.route,
            to = %project.id,
            host = project.host.as_deref().unwrap_or("<local>"),
            cwd = %project.cwd,
            intent,
            "transferring the caller"
        );
        self.drop_agent().await;
        let (model, model_note) = self
            .select_transfer_model(&project, requested_model, requested_thinking)
            .await;
        let prepared = self.run_prepare(&project).await;
        let session_id = uuid_like();
        self.project = Some(project.clone());
        self.route = project.id.clone();
        self.live_leg.set_session(&self.route, &session_id);
        self.model_spec = model.clone();
        self.session_id = session_id.clone();
        let session = match self.start_agent(&project, &model, &session_id).await {
            Ok(s) => s,
            Err(e) => {
                tracing::error!(
                    project = %project.id,
                    host = project.host.as_deref().unwrap_or("<local>"),
                    error = %e,
                    "could not connect to the project"
                );
                self.drop_agent().await;
                self.operator_note = Some(format!("Transfer to {} failed: {e}", project.id));
                return self.reply_transfer_error(
                    handoff,
                    format!("I couldn't get {} on the line: {e}", project.id),
                    Some(e.to_string()),
                );
            }
        };
        self.agent = Some(session);
        // Publish a self-consistent PBX state before the await. A page rescue
        // can cancel this transfer at any suspension point; once `agent` is
        // owned here, the route must identify it so force_hangup will reap it.
        self.set_active_session(self.agent.clone()).await;
        self.announce_route().await;
        let workspace = if prepared.is_empty() {
            String::new()
        } else {
            format!("\nState of your working copy: {prepared}\n")
        };
        let intro = format!("The switchboard has just connected a caller to you.\nThey asked for: {}\n{workspace}Greet them in one short sentence and start if appropriate.", if intent.is_empty() { "nothing specific" } else { intent });
        let Some(session) = self.agent.as_ref() else {
            return self.reply_transfer_error(
                handoff,
                format!("{} did not come up.", project.id),
                Some("project session was not created".into()),
            );
        };
        let turn = match session.prompt(&intro).await {
            Ok(t) => t,
            Err(e) => {
                tracing::warn!(project = %project.id, error = %e, "intro prompt to the project failed");
                Turn {
                    text: String::new(),
                    signals: vec![],
                    failed: true,
                    error: e.to_string(),
                }
            }
        };
        if turn.failed && turn.text.is_empty() {
            let detail = if !turn.error.trim().is_empty() {
                turn.error
            } else {
                let tail = session.stderr_tail(5);
                if tail.is_empty() {
                    "the agent never answered".to_owned()
                } else {
                    tail
                }
            };
            tracing::error!(project = %project.id, %detail, "the project never answered its intro; returning to the operator");
            self.drop_agent().await;
            self.operator_note = Some(format!("The transfer to {} failed: {detail}", project.id));
            return self.reply_transfer_error(
                handoff,
                format!("{} didn't pick up: {detail}", project.id),
                Some(detail),
            );
        }
        self.reply_with_transfer_turn(turn, handoff, model_note)
    }
    async fn start_agent(
        &self,
        project: &Project,
        model: &str,
        session_id: &str,
    ) -> Result<PiSession, PiSessionError> {
        let mut env = self.env.clone();
        let agent_env = self.agent_env(session_id);
        env.extend(agent_env.clone());
        let extension = if project.is_remote() {
            if project.stage_extension {
                self.stage_extension(project.host.as_deref().unwrap_or_default())
                    .await
            } else {
                None
            }
        } else {
            self.agent_extension_file
                .as_deref()
                .filter(|path| Path::new(path).is_file())
                .map(str::to_owned)
        };
        // If staging is unavailable, omit -e deliberately. The brief then
        // instructs the runtime to use the RETURN sentinel rather than lying
        // about a tool that never loaded.
        let brief = self.agent_brief(project, extension.is_some());
        let argv = if project.is_remote() {
            remote_argv(
                project.host.as_deref().unwrap_or_default(),
                &project.cwd,
                &project.runtime,
                (!model.is_empty()).then_some(model),
                extension.as_deref(),
                Some(&brief),
                Some(session_id),
                &project.extra_args,
                &agent_env,
            )
        } else {
            let mut a = vec![project.runtime.clone(), "--mode".into(), "rpc".into()];
            if !model.is_empty() {
                a.extend(["--model".into(), model.into()]);
            }
            a.extend([
                "--session-id".into(),
                session_id.into(),
                "--append-system-prompt".into(),
                brief,
            ]);
            if let Some(ext) = extension {
                a.extend(["-e".into(), ext]);
            }
            a.extend(project.extra_args.clone());
            a
        };
        PiSession::start(
            argv,
            project.id.clone(),
            (!project.is_remote())
                .then(|| project.cwd.clone())
                .filter(|p| !p.is_empty()),
            Some(env),
            Duration::from_secs(600),
            self.activity_callback.clone(),
        )
        .await
    }
    fn agent_brief(&self, project: &Project, has_tool: bool) -> String {
        let mut brief = AGENT_BRIEF_HEADER.replace("{project}", &project.id);
        brief.push_str(if has_tool {
            SPEAK_BRIEF
        } else {
            FALLBACK_BRIEF
        });
        if has_tool {
            brief.push_str(" When the caller asks for the operator, call return_to_operator; if the extension cannot be used, end with ");
            brief.push_str(RETURN_SENTINEL);
            brief.push_str(". If they ask for another project, use transfer_to_project and pass their request as intent. Known direct transfer targets:\n");
            let others = self
                .registry
                .projects
                .iter()
                .filter(|candidate| candidate.id != project.id)
                .map(|candidate| {
                    format!(
                        "- {} — {}",
                        candidate.id,
                        if candidate.description.is_empty() {
                            "no description"
                        } else {
                            candidate.description.as_str()
                        }
                    )
                })
                .collect::<Vec<_>>();
            brief.push_str(
                if others.is_empty() {
                    "- none".to_owned()
                } else {
                    others.join("\n")
                }
                .as_str(),
            );
            brief.push_str(". If the requested project is not listed, return to the operator rather than guessing.");
            if self.model_swaps {
                brief.push_str(" If the caller asks to change model or thinking level, use set_model; pass the provider/model when known and keep_context unless they ask to start over. Do not claim a swap happened beside that tool call.");
            }
        } else {
            brief.push_str(" When the caller asks for the operator, end with ");
            brief.push_str(RETURN_SENTINEL);
            brief.push_str(". Do not claim that a switchboard tool is available.");
        }
        brief.push_str(" Keep spoken updates brief and plain; leave code, paths, and detail in written output.");
        brief
    }

    async fn run_prepare(&self, project: &Project) -> String {
        if project.prepare.is_empty() {
            return String::new();
        }
        let mut command = if project.is_remote() {
            let remote = format!(
                "cd {} && {}",
                crate::pi_client::shell_quote(&project.cwd),
                project.prepare
            );
            let mut command = Command::new("ssh");
            command.args([
                "-T",
                "-o",
                "BatchMode=yes",
                "-o",
                "ConnectTimeout=10",
                project.host.as_deref().unwrap_or_default(),
                &remote,
            ]);
            command
        } else {
            let mut command = Command::new("sh");
            command.args(["-c", project.prepare.as_str()]);
            if !project.cwd.is_empty() {
                command.current_dir(&project.cwd);
            }
            command
        };
        command
            .envs(&self.env)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        crate::pi_client::isolate_process(&mut command);
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(error) => {
                tracing::warn!(project = %project.id, %error, "prepare could not start");
                return String::new();
            }
        };
        let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
        let stdout_task = child.stdout.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, PREPARE_OUTPUT_LIMIT).await
            })
        });
        let stderr_task = child.stderr.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, CHILD_ERROR_LIMIT).await
            })
        });
        let status = match timeout(Duration::from_secs(120), child.wait()).await {
            Ok(Ok(status)) => {
                process_guard.disarm();
                status
            }
            Ok(Err(error)) => {
                tracing::warn!(project = %project.id, %error, "prepare failed");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return String::new();
            }
            Err(_) => {
                tracing::warn!(project = %project.id, "prepare timed out");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return String::new();
            }
        };
        let stdout = join_output(stdout_task).await;
        let stderr = join_output(stderr_task).await;
        if stdout.truncated {
            tracing::warn!(project = %project.id, "prepare output exceeded the size limit");
            return "workspace refresh output was too large".into();
        }
        let report = String::from_utf8_lossy(&stdout.bytes).trim().to_owned();
        if !status.success() {
            let detail = String::from_utf8_lossy(&stderr.bytes)
                .trim()
                .chars()
                .take(300)
                .collect::<String>();
            tracing::warn!(project = %project.id, code = ?status.code(), %detail, "prepare exited unsuccessfully");
            return if report.is_empty() {
                format!(
                    "could not be refreshed ({})",
                    if detail.is_empty() {
                        "unknown error"
                    } else {
                        &detail
                    }
                )
            } else {
                report
            };
        }
        if !report.is_empty() {
            tracing::info!(project = %project.id, %report, "prepare reported the state of the working copy");
        }
        report
    }

    async fn stage_extension(&self, host: &str) -> Option<String> {
        if let Some(staged) = self.staged_extensions.lock().await.get(host).cloned() {
            return staged;
        }
        let staged = self.upload_extension(host).await;
        self.staged_extensions
            .lock()
            .await
            .insert(host.to_owned(), staged.clone());
        staged
    }

    async fn upload_extension(&self, host: &str) -> Option<String> {
        self.upload_extension_with("ssh", host).await
    }

    async fn upload_extension_with(&self, ssh_program: &str, host: &str) -> Option<String> {
        // Silently returning None here costs the agent its `speak` and
        // `diagram` tools and quietly rewrites its system prompt to use the
        // sentinel instead — a large behavior change from one unset path.
        let Some(source) = self.agent_extension_file.as_deref() else {
            tracing::warn!(
                host,
                "no agent extension file to stage; using sentinel fallback"
            );
            return None;
        };
        let contents = match tokio::fs::read(source).await {
            Ok(contents) => contents,
            Err(error) => {
                tracing::warn!(%error, source, "could not read project extension; using sentinel fallback");
                return None;
            }
        };
        let name = Path::new(source).file_name()?.to_string_lossy();
        let cache = self.remote_cache_dir.trim_end_matches('/');
        let target = format!("{cache}/{name}");
        let cache_path = if cache.starts_with('/') {
            crate::pi_client::shell_quote(cache)
        } else {
            format!("\"$HOME\"/{}", crate::pi_client::shell_quote(cache))
        };
        let target_path = if target.starts_with('/') {
            crate::pi_client::shell_quote(&target)
        } else {
            format!("\"$HOME\"/{}", crate::pi_client::shell_quote(&target))
        };
        let command = format!(
            "set -e; mkdir -p {cache_path}; cat > {target_path}; printf '%s' {target_path}"
        );
        let mut stage_command = Command::new(ssh_program);
        stage_command
            .args([
                "-T",
                "-o",
                "BatchMode=yes",
                "-o",
                "ConnectTimeout=10",
                host,
                &command,
            ])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        crate::pi_client::isolate_process(&mut stage_command);
        let mut child = match stage_command.spawn() {
            Ok(child) => child,
            Err(error) => {
                tracing::warn!(%error, host, "could not stage project extension; using sentinel fallback");
                return None;
            }
        };
        let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
        let mut stdin = child.stdin.take();
        let stdout_task = child.stdout.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, STAGE_OUTPUT_LIMIT).await
            })
        });
        let stderr_task = child.stderr.take().map(|mut output| {
            tokio::spawn(async move {
                crate::pi_client::drain_bounded(&mut output, CHILD_ERROR_LIMIT).await
            })
        });
        let interaction = async {
            if let Some(mut input) = stdin.take() {
                match input.write_all(&contents).await {
                    Ok(()) => {}
                    // The remote stopped reading, which normally means the
                    // staging command already failed. Its exit status and
                    // stderr name the real cause -- a missing directory, a
                    // permission denial -- and that is what the warning below
                    // should carry, not the broken pipe it caused.
                    Err(error) if error.kind() == std::io::ErrorKind::BrokenPipe => {}
                    Err(error) => return Err(error),
                }
                drop(input);
            }
            child.wait().await
        };
        let status = match timeout(Duration::from_secs(30), interaction).await {
            Ok(Ok(status)) => {
                process_guard.disarm();
                status
            }
            Ok(Err(error)) => {
                tracing::warn!(%error, host, "remote extension staging failed; using sentinel fallback");
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return None;
            }
            Err(_) => {
                tracing::warn!(
                    host,
                    "remote extension staging timed out; using sentinel fallback"
                );
                crate::pi_client::terminate_process(&mut child).await;
                process_guard.disarm();
                abort_output(stdout_task);
                abort_output(stderr_task);
                return None;
            }
        };
        let stdout = join_output(stdout_task).await;
        let stderr = join_output(stderr_task).await;
        if !status.success() || stdout.truncated {
            let detail = String::from_utf8_lossy(&stderr.bytes)
                .trim()
                .chars()
                .take(300)
                .collect::<String>();
            tracing::warn!(
                ?detail,
                host,
                code = ?status.code(),
                truncated = stdout.truncated,
                "remote extension staging failed; using sentinel fallback"
            );
            return None;
        }
        let staged = String::from_utf8_lossy(&stdout.bytes).trim().to_owned();
        if staged.is_empty() {
            tracing::warn!(
                host,
                "remote extension staging reported no path; using sentinel fallback"
            );
            return None;
        }
        tracing::info!(host, path = %staged, "staged the switchboard tool");
        Some(staged)
    }

    fn agent_env(&self, session_token: &str) -> HashMap<String, String> {
        let mut e = HashMap::from([
            (String::from("SWITCHBOARD_SESSION"), String::from("1")),
            (
                String::from("SWITCHBOARD_SESSION_TOKEN"),
                session_token.to_owned(),
            ),
        ]);
        for (key, value) in [
            ("SWITCHBOARD_SPEAK_URL", &self.speak_url),
            ("SWITCHBOARD_STATE_URL", &self.state_url),
            ("SWITCHBOARD_DIAGRAM_URL", &self.diagram_url),
            ("SWITCHBOARD_PERSONA", &self.persona),
        ] {
            if !value.is_empty() {
                e.insert(key.into(), value.clone());
            }
        }
        e
    }
    async fn load_catalog(&mut self, project: &Project) {
        let key = format!(
            "{}\0{}",
            project.host.as_deref().unwrap_or(""),
            project.runtime
        );
        if let std::collections::hash_map::Entry::Vacant(e) = self.catalogs.entry(key) {
            let catalog = fetch_catalog(&crate::pi_client::list_models_argv(
                &project.runtime,
                project.host.as_deref().unwrap_or(""),
            ))
            .await;
            e.insert(catalog);
        }
    }

    async fn resolve_model(
        &mut self,
        project: &Project,
        model: &str,
        thinking: &str,
    ) -> Result<ModelChoice, ModelError> {
        let requested = if model.is_empty() {
            project
                .model
                .as_deref()
                .or(self.agent_model.as_deref())
                .unwrap_or("")
                .to_owned()
        } else {
            model.to_owned()
        };
        self.load_catalog(project).await;
        let key = format!(
            "{}\0{}",
            project.host.as_deref().unwrap_or(""),
            project.runtime
        );
        self.catalogs
            .get(&key)
            .ok_or_else(|| ModelError("the model catalog was unavailable".into()))?
            .resolve(&requested, thinking)
    }

    async fn select_transfer_model(
        &mut self,
        project: &Project,
        requested_model: &str,
        requested_thinking: &str,
    ) -> (String, String) {
        let fallback = pin_thinking(
            project
                .model
                .as_deref()
                .or(self.agent_model.as_deref())
                .unwrap_or(""),
            &self.agent_thinking,
        );
        if !self.model_swaps {
            return (fallback, String::new());
        }
        if requested_model.trim().is_empty() {
            self.load_catalog(project).await;
            return (fallback, String::new());
        }

        match self
            .resolve_model(project, requested_model, requested_thinking)
            .await
        {
            Ok(choice) => (
                pin_thinking(&choice.spec(), &self.agent_thinking),
                String::new(),
            ),
            Err(error) => (fallback, format!("About the model: {error}")),
        }
    }

    async fn redial(
        &mut self,
        model: &str,
        thinking: &str,
        intent: &str,
        keep_context: bool,
    ) -> Reply {
        let Some(project) = self.project.clone() else {
            return self.reply(["There is no project on the line."], None);
        };
        if !self.model_swaps {
            return self.reply(["Model swapping is turned off on this switchboard."], None);
        }
        let requested_model = if model.is_empty() && !self.model_spec.is_empty() {
            self.model_spec.clone()
        } else {
            model.to_owned()
        };
        let (_, _, current_thinking) = crate::models::parse_spec(&self.model_spec);
        let level = if thinking.is_empty() {
            if !current_thinking.is_empty() {
                current_thinking
            } else {
                self.agent_thinking.clone()
            }
        } else {
            match normalize_thinking(thinking) {
                Ok(v) => v,
                Err(e) => return self.reply([e.to_string()], Some(e.to_string())),
            }
        };
        let choice = match self.resolve_model(&project, &requested_model, &level).await {
            Ok(choice) => choice,
            Err(error) => {
                // Refusing is the safe outcome — the live leg keeps running —
                // but it looks identical to a swap that never happened.
                tracing::info!(project = %project.id, requested = %requested_model, %error, "refusing a model swap");
                return self.reply(
                    [format!("I didn't switch: {error}")],
                    Some(error.to_string()),
                );
            }
        };
        let spec = choice.spec();
        if keep_context && spec == self.model_spec {
            return self.reply([format!("Already on {}.", choice.spoken())], None);
        }
        let session_id = if keep_context {
            self.session_id.clone()
        } else {
            uuid_like()
        };
        tracing::info!(
            project = %project.id,
            from = %self.model_spec,
            to = %spec,
            context = if keep_context { "kept" } else { "cleared" },
            "swapping the model on the live leg"
        );
        self.drop_agent().await;
        self.project = Some(project.clone());
        self.route = project.id.clone();
        self.live_leg.set_session(&self.route, &session_id);
        self.session_id = session_id.clone();
        self.model_spec = spec.clone();
        match self.start_agent(&project, &spec, &session_id).await {
            Ok(session) => {
                let project_name = project.id.clone();
                self.agent = Some(session);
                self.route = project.id.clone();
                self.live_leg.set_session(&self.route, &session_id);
                self.project = Some(project);
                self.session_id = session_id;
                self.model_spec = spec.clone();
                // Keep route ownership coherent if a forced page action aborts
                // the redial while its session handle is being published.
                self.set_active_session(self.agent.clone()).await;
                self.announce_route().await;
                let prompt = if keep_context {
                    format!(
                        "You are now running on {spec}. Continue the conversation.{}",
                        if intent.trim().is_empty() {
                            String::new()
                        } else {
                            format!(" The caller also asked: {}.", intent.trim())
                        }
                    )
                } else {
                    format!(
                        "You are now running on {spec}. The earlier conversation was deliberately cleared; start fresh.{}",
                        if intent.trim().is_empty() {
                            String::new()
                        } else {
                            format!(" The caller asked: {}.", intent.trim())
                        }
                    )
                };
                let Some(session) = self.agent.clone() else {
                    return self
                        .return_operator("project session disappeared during redial")
                        .await;
                };
                let turn = match session.prompt(&prompt).await {
                    Ok(turn) => turn,
                    Err(error) => Turn {
                        text: String::new(),
                        signals: vec![],
                        failed: true,
                        error: error.to_string(),
                    },
                };
                if turn.failed && turn.text.is_empty() {
                    let detail = if turn.error.is_empty() {
                        session.stderr_tail(5)
                    } else {
                        turn.error.clone()
                    };
                    let detail = if detail.is_empty() {
                        "the agent never answered".to_owned()
                    } else {
                        detail
                    };
                    tracing::error!(project = %project_name, %spec, %detail, "the swapped leg never answered");
                    self.drop_agent().await;
                    self.operator_note = Some(format!(
                        "{project_name} could not be restarted on {spec}: {detail}"
                    ));
                    return self.reply(
                        [format!(
                            "{project_name} didn't come back on {spec}: {detail}"
                        )],
                        Some(detail),
                    );
                }
                self.reply_with_turn(turn)
            }
            Err(error) => {
                tracing::error!(project = %project.id, %spec, %error, "could not restart the leg on the new model");
                self.drop_agent().await;
                let note = format!("{} could not be restarted on {}: {error}", project.id, spec);
                self.operator_note = Some(note);
                self.reply(
                    [format!(
                        "I couldn't bring {} back on {}: {error}",
                        project.id, spec
                    )],
                    Some(error.to_string()),
                )
            }
        }
    }
    async fn return_operator(&mut self, note: &str) -> Reply {
        self.drop_agent().await;
        // Prompt the operator immediately so an onward destination in the note
        // is acted on now, not stapled onto the caller's next utterance.
        let note = note.to_owned();
        let reply = self.handle_operator(&format!("[switchboard] {note}")).await;
        if reply.error.is_some() {
            self.operator_note = Some(note);
        }
        if reply.text.is_empty() {
            self.reply(["You're back with the operator."], reply.error)
        } else {
            reply
        }
    }
    async fn recover_operator(&mut self, error: String) -> Reply {
        tracing::warn!(%error, "dropping and rebuilding the operator leg");
        if let Some(s) = self.operator.take() {
            s.close().await;
        }
        self.set_active_session(None).await;
        self.reply(
            ["The operator dropped the line. Say that again and I'll pick it back up."],
            Some(error),
        )
    }
    async fn drop_agent(&mut self) {
        let was = self.route.clone();
        if let Some(s) = self.agent.take() {
            s.close().await;
        }
        self.set_active_session(self.operator.clone()).await;
        self.project = None;
        self.route = OPERATOR.into();
        self.live_leg.set_route(OPERATOR);
        self.model_spec.clear();
        self.session_id.clear();
        if was != OPERATOR {
            self.announce_route().await;
        }
    }
    fn reply<I, S>(&self, texts: I, error: Option<String>) -> Reply
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        Reply::new(
            &self.route,
            &self.route_label(),
            texts
                .into_iter()
                .map(|text| Utterance {
                    text: text.into(),
                    synthesize: true,
                })
                .collect(),
            error,
        )
    }
    fn reply_with_turn(&self, turn: Turn) -> Reply {
        let spoke = turn.agent_spoke();
        let failed = turn.failed;
        let error = turn.error;
        Reply::new(
            &self.route,
            &self.route_label(),
            vec![Utterance {
                text: turn.text,
                synthesize: !spoke,
            }],
            failed.then_some(error),
        )
    }
    fn reply_transfer_error(
        &self,
        handoff: String,
        message: String,
        error: Option<String>,
    ) -> Reply {
        Reply::new(
            &self.route,
            &self.route_label(),
            vec![
                Utterance {
                    text: handoff,


… payload truncated

text:
            .map_err(|error| PiSessionError(format!("agent process closed its input: {error}")))?;
        stdin
            .flush()
            .await
            .map_err(|error| PiSessionError(format!("agent process closed its input: {error}")))
    }

    async fn collect(&self) -> Result<Turn, PiSessionError> {
        let mut chunks = Vec::new();
        let mut signals = Vec::new();
        let mut error = String::new();
        loop {
            let read = {
                let mut stdout = self.inner.stdout.lock().await;
                timeout(
                    self.inner.turn_timeout,
                    read_limited_line(&mut *stdout, STREAM_LIMIT),
                )
                .await
            };
            let label = &self.inner.label;
            let line = match read {
                Ok(Ok(LimitedLine::Line(line))) => line,
                Ok(Ok(LimitedLine::Eof)) => {
                    tracing::warn!(
                        %label,
                        stderr_lines = self.stderr_tail(5).lines().count(),
                        "agent stream ended mid-turn"
                    );
                    return Ok(Turn {
                        text: chunks.join("\n"),
                        signals,
                        failed: true,
                        error,
                    });
                }
                Ok(Ok(LimitedLine::TooLong)) => {
                    tracing::error!(%label, limit = STREAM_LIMIT, "oversized RPC event; dropping the leg");
                    self.close().await;
                    return Ok(Turn {
                        text: String::new(),
                        signals,
                        failed: true,
                        error: "the agent sent something too big to read".into(),
                    });
                }
                Ok(Err(error)) => {
                    tracing::error!(%label, %error, "could not read agent output");
                    return Err(PiSessionError(format!(
                        "could not read agent output: {error}"
                    )));
                }
                Err(_) => {
                    // The most common wedged-agent symptom in production, and
                    // until now the one that left the least behind.
                    tracing::warn!(
                        %label,
                        timeout = ?self.inner.turn_timeout,
                        stderr_lines = self.stderr_tail(5).lines().count(),
                        "agent went silent past the turn deadline; dropping the leg"
                    );
                    self.close().await;
                    return Ok(Turn {
                        text: String::new(),
                        signals,
                        failed: true,
                        error: "the agent stopped responding".into(),
                    });
                }
            };
            let line = String::from_utf8_lossy(&line);
            let line = line.trim_end_matches(['\r', '\n']);
            if line.is_empty() {
                continue;
            }
            let event: Value = match serde_json::from_str(line) {
                Ok(event) => event,
                // Skipping is right — a runtime that prints a banner must not
                // fail the call — but the skipped line is worth keeping.
                Err(error) => {
                    tracing::debug!(
                        %label,
                        %error,
                        bytes = line.len(),
                        "skipping a non-JSON line from the agent"
                    );
                    continue;
                }
            };
            match event.get("type").and_then(Value::as_str) {
                Some("message_update") => {
                    if event
                        .pointer("/assistantMessageEvent/type")
                        .and_then(Value::as_str)
                        == Some("text_end")
                    {
                        if let Some(content) = event
                            .pointer("/assistantMessageEvent/content")
                            .and_then(Value::as_str)
                            .filter(|content| !content.trim().is_empty())
                        {
                            let collected = chunks.iter().map(String::len).sum::<usize>();
                            if collected.saturating_add(content.len()) > STREAM_LIMIT {
                                tracing::error!(
                                    %label,
                                    collected,
                                    limit = STREAM_LIMIT,
                                    "agent produced too much text in one turn; dropping the leg"
                                );
                                self.close().await;
                                return Ok(Turn {
                                    text: String::new(),
                                    signals,
                                    failed: true,
                                    error: "the agent produced too much text in one turn".into(),
                                });
                            }
                            chunks.push(content.trim().to_owned());
                        }
                    }
                }
                Some("message_end") => {
                    let message = event.get("message").and_then(Value::as_object);
                    if message
                        .and_then(|message| message.get("role"))
                        .and_then(Value::as_str)
                        == Some("assistant")
                        && message
                            .and_then(|message| message.get("stopReason"))
                            .and_then(Value::as_str)
                            == Some(ERROR_STOP_REASON)
                    {
                        let raw = message.and_then(|message| message.get("errorMessage"));
                        // Keep the same sanitized detail that the caller hears;
                        // raw provider errors can contain prompts or credentials.
                        let sanitized = spoken_error(raw);
                        tracing::error!(
                            %label,
                            error = %sanitized,
                            "the agent's model call failed"
                        );
                        error = sanitized;
                    }
                }
                Some("tool_execution_start") => {
                    let name = event.get("toolName").and_then(Value::as_str).unwrap_or("");
                    if [TRANSFER_TOOL, RETURN_TOOL, SET_MODEL_TOOL, SPEAK_TOOL].contains(&name) {
                        let args = event
                            .get("args")
                            .and_then(Value::as_object)
                            .cloned()
                            .unwrap_or_default();
                        // The signal name and argument count are enough to
                        // trace routing without writing speech or model content.
                        tracing::info!(
                            %label,
                            signal = name,
                            arg_count = args.len(),
                            "agent raised a routing signal"
                        );
                        signals.push(Signal {
                            name: name.into(),
                            args,
                        });
                    }
                    self.report_activity("start", name, activity_detail(event.get("args")))
                        .await;
                }
                Some("tool_execution_end") => {
                    self.report_activity(
                        "end",
                        event.get("toolName").and_then(Value::as_str).unwrap_or(""),
                        String::new(),
                    )
                    .await
                }
                Some("extension_error") => {
                    tracing::error!(
                        label = %self.inner.label,
                        error = ?event.get("error"),
                        "agent extension error"
                    );
                }
                Some("agent_settled") => break,
                _ => {}
            }
        }
        let mut text = chunks.join("\n").trim().to_owned();
        if text.contains(RETURN_SENTINEL) {
            text = text.replace(RETURN_SENTINEL, "").trim().to_owned();
            if !signals.iter().any(|signal| signal.name == RETURN_TOOL) {
                signals.push(Signal {
                    name: RETURN_TOOL.into(),
                    args: Map::from_iter([(String::from("via"), Value::String("sentinel".into()))]),
                });
            }
        }
        Ok(Turn {
            text,
            signals,
            failed: !error.is_empty(),
            error,
        })
    }

    async fn report_activity(&self, state: &str, tool: &str, detail: String) {
        if let Some(callback) = &self.inner.on_activity {
            let callback = Arc::clone(callback);
            let activity = Activity {
                state: state.into(),
                tool: tool.into(),
                detail,
                label: self.inner.label.clone(),
            };
            if let Err(panic) = AssertUnwindSafe(callback(activity)).catch_unwind().await {
                tracing::error!(
                    label = %self.inner.label,
                    tool,
                    panic = %panic_message(&panic),
                    "activity callback panicked"
                );
            }
        }
    }
}

/// Put a supervised command in its own process group where the platform
/// supports it. Pi and SSH may launch helpers; cancellation must reap the whole
/// local tree rather than only its top-level shell/client.
pub(crate) fn isolate_process(command: &mut Command) {
    command.kill_on_drop(true);
    #[cfg(unix)]
    command.process_group(0);
}

/// Synchronous cancellation backstop for async operations that own child
/// process trees. `kill_on_drop` only targets the immediate process; this guard
/// also terminates helpers launched by a shell or runtime if the future is
/// aborted before it can run its async cleanup path.
pub(crate) struct ProcessTreeGuard(StdMutex<Option<i32>>);

impl ProcessTreeGuard {
    pub(crate) fn new(child: &Child) -> Self {
        #[cfg(unix)]
        let pid = child.id().map(|pid| pid as i32);
        #[cfg(not(unix))]
        let pid = None;
        Self(StdMutex::new(pid))
    }

    pub(crate) fn disarm(&self) {
        if let Ok(mut pid) = self.0.lock() {
            pid.take();
        }
    }
}

impl Drop for ProcessTreeGuard {
    fn drop(&mut self) {
        #[cfg(unix)]
        if let Ok(pid) = self.0.get_mut() {
            if let Some(pid) = pid.take() {
                unsafe {
                    libc::kill(-pid, libc::SIGKILL);
                }
            }
        }
    }
}

pub(crate) async fn terminate_process(child: &mut Child) {
    match child.try_wait() {
        Ok(Some(_)) => return,
        Ok(None) => {}
        Err(_) => {
            let _ = child.kill().await;
            let _ = child.wait().await;
            return;
        }
    }
    #[cfg(unix)]
    if let Some(pid) = child.id() {
        unsafe {
            libc::kill(-(pid as i32), libc::SIGKILL);
        }
    }
    #[cfg(not(unix))]
    let _ = child.kill().await;
    let _ = child.wait().await;
}

#[derive(Debug, PartialEq, Eq)]
enum LimitedLine {
    Eof,
    Line(Vec<u8>),
    TooLong,
}

/// Read one JSONL record without allowing a missing newline to grow memory
/// without bound. `AsyncBufReadExt::read_line` only reports the length after it
/// has allocated the whole record, which defeats `STREAM_LIMIT` for a wedged or
/// hostile child process.
async fn read_limited_line<R>(reader: &mut R, limit: usize) -> std::io::Result<LimitedLine>
where
    R: AsyncBufRead + Unpin,
{
    let mut line = Vec::with_capacity(limit.min(8 * 1024));
    loop {
        let available = reader.fill_buf().await?;
        if available.is_empty() {
            return Ok(if line.is_empty() {
                LimitedLine::Eof
            } else {
                LimitedLine::Line(line)
            });
        }

        let take = available
            .iter()
            .position(|byte| *byte == b'\n')
            .map_or(available.len(), |position| position + 1);
        if line.len().saturating_add(take) > limit {
            return Ok(LimitedLine::TooLong);
        }
        line.extend_from_slice(&available[..take]);
        reader.consume(take);
        if line.last() == Some(&b'\n') {
            return Ok(LimitedLine::Line(line));
        }
    }
}

async fn drain_stderr(stderr: ChildStderr, tail: Arc<StdMutex<Vec<String>>>, label: String) {
    let mut stderr = BufReader::new(stderr);
    let mut chunk = [0_u8; 8192];
    let mut line = Vec::new();
    let mut oversized = false;
    loop {
        let read = match stderr.read(&mut chunk).await {
            Ok(0) => break,
            // A pipe that fails is not the same as a process that finished
            // talking, and only one of the two is worth investigating.
            Err(error) => {
                tracing::error!(%label, %error, "agent stderr drain failed");
                break;
            }
            Ok(read) => read,
        };
        for byte in &chunk[..read] {
            if *byte == b'\n' {
                if oversized {
                    push_stderr(&tail, "[oversized stderr line]".into());
                } else {
                    let value = String::from_utf8_lossy(&line)
                        .trim_end_matches('\r')
                        .to_owned();
                    if !value.trim().is_empty() {
                        tracing::debug!(%label, bytes = value.len(), "agent wrote to stderr");
                        push_stderr(&tail, value);
                    }
                }
                line.clear();
                oversized = false;
            } else if line.len() < STDERR_LINE_LIMIT {
                line.push(*byte);
            } else {
                oversized = true;
            }
        }
    }
    if oversized {
        push_stderr(&tail, "[oversized stderr line]".into());
    } else if !line.is_empty() {
        let value = String::from_utf8_lossy(&line).trim().to_owned();
        if !value.is_empty() {
            push_stderr(&tail, value);
        }
    }
}

/// The message a caught panic carried.
///
/// `catch_unwind` hands back a boxed `Any`, and reporting only that a callback
/// "failed" throws away the one part of it worth reading. `panic!` produces
/// either a `&'static str` or a `String`; anything else is named rather than
/// silently rendered as nothing.
pub(crate) fn panic_message(panic: &(dyn std::any::Any + Send)) -> String {
    panic
        .downcast_ref::<&'static str>()
        .map(|text| (*text).to_owned())
        .or_else(|| panic.downcast_ref::<String>().cloned())
        .unwrap_or_else(|| "<non-string panic payload>".to_owned())
}

fn push_stderr(tail: &StdMutex<Vec<String>>, line: String) {
    if let Ok(mut tail) = tail.lock() {
        tail.push(line);
        if tail.len() > 20 {
            let remove = tail.len() - 20;
            tail.drain(..remove);
        }
    }
}

#[derive(Debug, Default)]
pub(crate) struct BoundedOutput {
    pub bytes: Vec<u8>,
    pub truncated: bool,
}

pub(crate) async fn drain_bounded<R>(mut reader: R, limit: usize) -> BoundedOutput
where
    R: AsyncRead + Unpin,
{
    let mut bytes = Vec::with_capacity(limit.min(8192));
    let mut chunk = [0_u8; 8192];
    let mut truncated = false;
    loop {
        match reader.read(&mut chunk).await {
            Ok(0) | Err(_) => break,
            Ok(read) => {
                let available = limit.saturating_sub(bytes.len());
                let keep = available.min(read);
                bytes.extend_from_slice(&chunk[..keep]);
                truncated |= keep < read;
            }
        }
    }
    BoundedOutput { bytes, truncated }
}

fn activity_detail(args: Option<&Value>) -> String {
    let Some(args) = args.and_then(Value::as_object) else {
        return String::new();
    };
    for key in ACTIVITY_ARG_ORDER {
        if let Some(value) = args
            .get(key)
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
        {
            let value = value.split_whitespace().collect::<Vec<_>>().join(" ");
            if value.chars().count() > ACTIVITY_DETAIL_CHARS {
                let clipped = value
                    .chars()
                    .take(ACTIVITY_DETAIL_CHARS)
                    .collect::<String>();
                return format!("{}…", clipped.trim_end());
            }
            return value;
        }
    }
    String::new()
}

fn spoken_error(detail: Option<&Value>) -> String {
    let mut first = detail
        .and_then(Value::as_str)
        .unwrap_or("the model call failed")
        .trim()
        .split('\n')
        .next()
        .unwrap_or("")
        .to_owned();
    for cut in ["; details=", " url=", "; stack="] {
        if let Some(index) = first.find(cut) {
            first.truncate(index);
        }
    }
    if first.chars().count() > ERROR_DETAIL_CHARS {
        first = first.chars().take(ERROR_DETAIL_CHARS).collect();
        first.push('…');
    }
    if first.trim().is_empty() {
        "the model call failed".into()
    } else {
        first
    }
}

pub fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}
pub fn list_models_argv(binary: &str, ssh_host: &str) -> Vec<String> {
    if ssh_host.is_empty() {
        return vec![binary.into(), "--list-models".into()];
    }
    vec![
        "ssh".into(),
        "-T".into(),
        "-o".into(),
        "BatchMode=yes".into(),
        "-o".into(),
        "ConnectTimeout=10".into(),
        ssh_host.into(),
        format!("{} --list-models", shell_quote(binary)),
    ]
}
pub fn local_argv(
    binary: &str,
    model: Option<&str>,
    system_prompt_file: Option<&Path>,
    extension: Option<&str>,
    extra_args: &[String],
) -> Result<Vec<String>, PiSessionError> {
    let mut argv = vec![binary.into(), "--mode".into(), "rpc".into()];
    if let Some(model) = model {
        argv.extend(["--model".into(), model.into()]);
    }
    if let Some(path) = system_prompt_file {
        let prompt = std::fs::read_to_string(path).map_err(|error| {
            PiSessionError(format!(
                "could not read system prompt {}: {error}",
                path.display()
            ))
        })?;
        argv.extend(["--system-prompt".into(), prompt]);
    }
    if let Some(extension) = extension {
        argv.extend(["-e".into(), extension.into()]);
    }
    argv.extend(extra_args.iter().cloned());
    Ok(argv)
}
#[allow(clippy::too_many_arguments)]
pub fn remote_argv(
    host: &str,
    cwd: &str,
    binary: &str,
    model: Option<&str>,
    extension: Option<&str>,
    append_system_prompt: Option<&str>,
    session_id: Option<&str>,
    extra_args: &[String],
    env: &HashMap<String, String>,
) -> Vec<String> {
    let mut remote = vec![binary.into(), "--mode".into(), "rpc".into()];
    if let Some(model) = model {
        remote.extend(["--model".into(), model.into()]);
    }
    if let Some(session_id) = session_id {
        remote.extend(["--session-id".into(), session_id.into()]);
    }
    if let Some(extension) = extension {
        remote.extend(["-e".into(), extension.into()]);
    }
    if let Some(prompt) = append_system_prompt {
        remote.extend(["--append-system-prompt".into(), prompt.into()]);
    }
    remote.extend(extra_args.iter().cloned());
    let mut environment = env.iter().collect::<Vec<_>>();
    environment.sort_unstable_by_key(|(left, _)| *left);
    let exports = environment
        .into_iter()
        .map(|(name, value)| format!("export {name}={}; ", shell_quote(value)))
        .collect::<Vec<_>>()
        .join("");
    let command = format!(
        "set -e; cd {}; {}exec {}",
        shell_quote(cwd),
        exports,
        remote
            .iter()
            .map(|arg| shell_quote(arg))
            .collect::<Vec<_>>()
            .join(" ")
    );
    vec![
        "ssh".into(),
        "-T".into(),
        "-o".into(),
        "BatchMode=yes".into(),
        "-o".into(),
        "ConnectTimeout=10".into(),
        host.into(),
        command,
    ]
}

/// Writes `body` as a `/bin/sh` script, marks it executable, and does not return
/// until the kernel will actually run it.
///
/// Tests run on many threads inside one process. Spawning a child forks, and the
/// fork duplicates every open descriptor, so a child forked while this file is
/// still being written inherits a writable descriptor to it and keeps that copy
/// until it execs. Linux refuses to execute a file any process holds open for
/// writing, so callers would otherwise fail intermittently with `ETXTBSY`.
///
/// Draining that window here — rather than retrying the operation under test —
/// is what keeps a real failure legible: the file is never rewritten after the
/// probe succeeds, so it stays runnable, and the code under test still executes
/// exactly once with its own errors surfacing unchanged.
